{"path":"about.html","content":"<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>About — {{BUSINESS_NAME}}</title>
    <style>
      :root{--bg:#f7f9fb;--card:#ffffff;--muted:#6b7280;--accent:#6b8f8f;--accent-2:#7a5c9e;--cta:#2c6f6f}
      *{box-sizing:border-box}
      body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.5;color:#0f172a;background:var(--bg);margin:0;padding:0}
      header{background:linear-gradient(180deg,rgba(122,92,158,0.06),transparent);padding:28px 20px;border-bottom:1px solid rgba(15,23,42,0.04)}
      .wrap{max-width:980px;margin:0 auto}
      .nav{display:flex;gap:16px;align-items:center;justify-content:space-between}
      .brand{display:flex;gap:12px;align-items:center}
      .logo{width:48px;height:48px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
      nav a{color:#0f172a;text-decoration:none;padding:8px 10px;border-radius:8px;font-weight:600}
      nav a:hover{background:rgba(15,23,42,0.04)}
      .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:40px 0}
      .title{font-size:clamp(20px,4vw,28px);font-weight:700;color:#071127;margin:0}
      .lede{color:var(--muted);margin:0;max-width:68ch}
      main{padding:28px 20px 80px}
      .grid{display:grid;grid-template-columns:1fr 360px;gap:24px}
      .card{background:var(--card);padding:20px;border-radius:12px;box-shadow:0 6px 24px rgba(12,24,56,0.06)}
      .small{color:var(--muted);font-size:14px}
      .role{display:flex;align-items:center;gap:12px}
      .avatar{width:64px;height:64px;border-radius:50%;background:linear-gradient(180deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
      .cta{display:inline-block;background:var(--cta);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
      .section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
      .muted{color:var(--muted)}
      /* Mood-to-Method */
      .mood{display:flex;gap:8px;flex-wrap:wrap}
      .mood button{padding:8px 12px;border-radius:999px;border:1px solid rgba(12,24,56,0.06);background:#fff;cursor:pointer;font-weight:600}
      .mood button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;border-color:transparent}
      .method{transition:all 360ms cubic-bezier(.2,.9,.3,1);padding:16px;border-radius:10px}
      .method.fade{opacity:0;transform:translateY(8px) scale(.995)}
      .fineprint{font-size:13px;color:var(--muted);margin-top:12px}
      footer{padding:28px 20px;border-top:1px solid rgba(15,23,42,0.04);background:linear-gradient(0deg,rgba(122,92,158,0.02),transparent)}
      .pattern{position:absolute;right:24px;top:10px;opacity:.12;width:220px;height:220px;background-image:url('assets/img/pattern.svg');background-size:cover;pointer-events:none}
    </style>
  </head>
  <body>
    <header>
      <div class="wrap nav">
        <div class="brand">
          <div class="logo">TP</div>
          <div>
            <div style="font-weight:800">{{BUSINESS_NAME}}</div>
            <div class="small">A practical, steadying clinical practice — {{CITY}}, {{STATE}}</div>
          </div>
        </div>
        <nav>
          <a href="index.html">Home</a>
          <a href="about.html" aria-current="page">Story</a>
          <a href="specialties.html">Services</a>
          <a href="approach.html">Method</a>
          <a href="fees.html">Investment</a>
          <a href="faq.html">Answers</a>
          <a href="book.html">Book</a>
          <a href="contact.html">Reach</a>
        </nav>
      </div>
    </header>

    <div class="wrap hero">
      <div>
        <h1 class="title">Calm guidance for real life—one step at a time</h1>
        <p class="lede">I work with adults who want steady progress: fewer days bogged down, more days where priorities feel manageable. My approach is collaborative, evidence-informed, and shaped by the realities of busy lives.</p>
      </div>
      <div class="pattern" aria-hidden="true"></div>
    </div>

    <main class="wrap">
      <div class="grid">
        <div>
          <div class="card">
            <div class="role">
              <div class="avatar">LM</div>
              <div>
                <div style="font-weight:800">Licensed Clinician</div>
                <div class="small">I provide individual therapy rooted in acceptance, clarity, and skill-building.</div>
              </div>
            </div>

            <section style="margin-top:18px">
              <h3 class="section-head"><span>How I work</span></h3>
              <p class="muted">Therapy is a conversation with structure: we name what's hard, try manageable experiments, and follow what changes. I draw from cognitive-behavioral approaches, behavioral activation, and mindfulness-based strategies—selected to fit your needs rather than a fixed protocol.</p>
            </section>

            <section style="margin-top:18px">
              <h3 class="section-head"><span>Confidentiality & boundaries</span></h3>
              <p class="muted">Sessions are confidential within legal and ethical limits. I will explain the scope of confidentiality during our first meeting and invite questions about what that means for you.</p>
            </section>

            <section style="margin-top:18px">
              <h3 class="section-head"><span>When this isn’t the right fit</span></h3>
              <p class="muted">I am not an emergency service. If you are in immediate danger or need urgent care, please call your local emergency number or a crisis line. I can help with referrals if a different level of care would serve you better.</p>
            </section>

            <div style="margin-top:18px"><a class="cta" id="about-main-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
            <div class="fineprint">Sessions offered via telehealth to {{STATE}} residents; in-person at select times. Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
          </div>

          <div class="card" style="margin-top:18px">
            <h4 style="margin:0 0 8px 0">Where to begin — pick how you feel</h4>
            <p class="small">Choose the word that best fits today. I’ll suggest a short focus and the call-to-action will change to match.</p>

            <div class="mood" role="tablist" aria-label="Mood selector" id="mood-about">
              <button data-key="overwhelmed">Overwhelmed</button>
              <button data-key="stuck">Stuck</button>
              <button data-key="racing">Racing thoughts</button>
              <button data-key="low">Flat / Low</button>
            </div>

            <div id="method-about" class="method card" style="margin-top:12px">
              <h4 style="margin:0 0 6px 0">Suggested starting point</h4>
              <p class="muted" id="method-text-about">Select how you feel to see a tailored first step and an aligned next move.</p>
              <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" id="mood-cta-about" class="cta">{{PRIMARY_CTA_LABEL}}</a></div>
            </div>
          </div>
        </div>

        <aside>
          <div class="card">
            <h4 style="margin-top:0">Common themes I support</h4>
            <ul class="small" style="padding-left:18px;margin:8px 0">
              <li>Difficulty managing daily overwhelm</li>
              <li>Transitions and life reorientation</li>
              <li>Persistent low mood or avoidance</li>
              <li>Stress that affects sleep and focus</li>
            </ul>
            <p class="small">If you’re curious whether I’m a fit, a brief intake helps us know what’s most helpful in the first few weeks.</p>
          </div>

          <div class="card" style="margin-top:18px">
            <h5 style="margin-top:0">Practical details</h5>
            <p class="small">I provide a safe, nonjudgmental space. Therapy is collaborative: we set goals together and check progress. If you need documentation or a letter, we’ll discuss limits and timelines.</p>
          </div>
        </aside>
      </div>

      <div style="margin-top:20px" class="card">
        <h4 style="margin-top:0">A note from the clinician</h4>
        <p class="muted">I aim to hold a reliably steady space—even when life feels disorderly. My work is about tiny, testable steps that respect your values and time. There are no guarantees in therapy, only a careful commitment to clarity, honesty, and your personal goals.</p>
      </div>
    </main>

    <footer>
      <div class="wrap small">&copy; <span id="year"></span> {{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <span>{{PHONE}}</span></div>
    </footer>

    <script>
      document.getElementById('year').textContent = new Date().getFullYear();

      // Mood-to-Method (About page)
      (function(){
        const map = {
          overwhelmed: {text: 'Start with a 10-minute grounding plan: three small actions to reduce immediate load (prioritise, delegate, pair down). Suggested first session focuses on making change feel do-able.', cta: 'Book a concise intake'},
          stuck: {text: 'Try a short behavioral experiment: identify one context where you’ll try a tiny change and review how it felt. Early work focuses on sparking movement, not perfection.', cta: 'Schedule a short consult'},
          racing: {text: 'We’ll try brief attention and sleep-focused strategies to ease mental speed. Early sessions emphasise pacing and breath practices that fit your day.', cta: 'Explore a first visit'},
          low: {text: 'Begin with small activation: one daily activity to shift energy, tracked compassionately. We aim for gentle momentum rather than pressure.', cta: 'Plan an introductory session'}
        };
        const container = document.getElementById('mood-about');
        const method = document.getElementById('method-about');
        const textEl = document.getElementById('method-text-about');
        const cta = document.getElementById('mood-cta-about');

        container.addEventListener('click', function(e){
          const btn = e.target.closest('button');
          if(!btn) return;
          Array.from(container.querySelectorAll('button')).forEach(b=>b.classList.remove('active'));
          btn.classList.add('active');
          const key = btn.dataset.key;
          method.classList.add('fade');
          setTimeout(()=>{
            textEl.textContent = map[key].text;
            cta.textContent = map[key].cta;
            method.classList.remove('fade');
          }, 160);
        });
      })();
    </script>
  </body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>Services — {{BUSINESS_NAME}}</title>
    <style>
      :root{--bg:#f6fbfb;--card:#ffffff;--muted:#50575e;--accent:#1f6f6f;--accent-2:#6a5aa6;--cta:#165a5a}
      body{font-family:system-ui,Segoe UI,Roboto,Arial;line-height:1.5;margin:0;color:#071127;background:var(--bg)}
      .wrap{max-width:980px;margin:0 auto;padding:24px}
      header{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
      .logo{display:flex;gap:12px;align-items:center}
      .logo-mark{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
      nav a{margin-left:12px;text-decoration:none;color:#071127;font-weight:700}
      .hero{background:linear-gradient(90deg,rgba(26,27,30,0.02),transparent);padding:22px;border-radius:12px;margin-bottom:18px}
      h1{margin:0;font-size:24px}
      p.lead{color:var(--muted);margin:8px 0 0}
      .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
      .svc{background:var(--card);padding:14px;border-radius:10px;box-shadow:0 8px 20px rgba(12,24,56,0.06);min-height:160px;display:flex;flex-direction:column;justify-content:space-between}
      .svc h3{margin:0 0 8px 0}
      .price{font-weight:800;font-size:20px;color:var(--cta)}
      .muted{color:var(--muted)}
      .controls{display:flex;gap:8px;align-items:center;margin-top:12px}
      .toggle{background:#fff;border-radius:999px;padding:6px;border:1px solid rgba(12,24,56,0.06);display:inline-flex}
      .toggle button{border:0;background:transparent;padding:8px 12px;border-radius:999px;cursor:pointer;font-weight:700}
      .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}
      .cmp{display:flex;gap:12px;align-items:baseline}
      .small{color:var(--muted);font-size:13px}
      .cta{display:inline-block;background:var(--cta);color:#fff;padding:8px 12px;border-radius:10px;text-decoration:none;font-weight:700}
      /* animated number */
      .num{font-feature-settings:'tnum';font-variant-numeric:tabular-nums}
    </style>
  </head>
  <body>
    <div class="wrap">
      <header>
        <div class="logo">
          <div class="logo-mark">TP</div>
          <div>
            <div style="font-weight:900">{{BUSINESS_NAME}}</div>
            <div class="small">Services & supports that meet you where you are</div>
          </div>
        </div>
        <nav>
          <a href="index.html">Home</a>
          <a href="about.html">Story</a>
          <a href="specialties.html" aria-current="page">Services</a>
          <a href="approach.html">Method</a>
          <a href="book.html">Book</a>
        </nav>
      </header>

      <section class="hero">
        <h1>Ways I can support you</h1>
        <p class="lead">Short-term supports and focused series—named to make choice clearer. Toggle the price view to compare per-session vs package options.</p>

        <div style="margin-top:12px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
          <div class="controls">
            <span class="small">View pricing:</span>
            <div class="toggle" role="tablist" id="price-toggle">
              <button data-mode="single" class="active">Per session</button>
              <button data-mode="package">Focus series</button>
            </div>
          </div>
          <div class="cmp">
            <div style="text-align:right">
              <div class="small">Example single session</div>
              <div class="price num" id="price-single">$150</div>
            </div>
            <div style="text-align:right">
              <div class="small">Example 6-session series</div>
              <div class="price num" id="price-package">$780</div>
            </div>
          </div>
        </div>
      </section>

      <div class="cards">
        <div class="svc">
          <div>
            <h3>Focused Sessions</h3>
            <p class="muted">One-off consultations for a clear question or immediate support: planning, coaching, or a clinical check-in.</p>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div class="price num" data-base="150" id="svc-1-price">$150</div>
              <div class="small">Typical session, 45–55 minutes</div>
            </div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="svc">
          <div>
            <h3>Six-Week Focus Series</h3>
            <p class="muted">A short, goal-oriented series with simple tracking and learning each week—good for targeted change.</p>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div class="price num" data-base="780" id="svc-2-price">$780</div>
              <div class="small">Six sessions, bundled</div>
            </div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="svc">
          <div>
            <h3>Maintenance Check-Ins</h3>
            <p class="muted">Periodic sessions to stay on track—planned every 4–6 weeks when progress is steady but you want a safety net.</p>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div class="price num" data-base="125" id="svc-3-price">$125</div>
              <div class="small">Shorter check-in visits</div>
            </div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </div>

      <div style="margin-top:18px;display:flex;gap:12px;align-items:center">
        <div class="card" style="padding:14px;flex:1">
          <h4 style="margin-top:0">How the comparator works</h4>
          <p class="small">Switch the view to see per-session labels or the package total. The numbers animate so you can notice the difference without doing the math.</p>
        </div>
        <div class="card" style="padding:14px;width:320px;">
          <h5 style="margin-top:0">Insurance & payments</h5>
          <p class="small">I accept credit card and secure online payment. If using insurance, I can provide a superbill for out-of-network reimbursement; please ask about details during scheduling.</p>
        </div>
      </div>

      <div style="margin-top:18px" class="small card">Please note: services are not emergency or crisis care. If you are in immediate danger or need urgent help, contact emergency services or a local crisis line.</div>
    </div>

    <script>
      // Pricing comparator logic with animated numbers
      (function(){
        const toggle = document.getElementById('price-toggle');
        const modeButtons = toggle.querySelectorAll('button');
        const items = [
          {el:document.getElementById('svc-1-price'), base:150},
          {el:document.getElementById('svc-2-price'), base:780},
          {el:document.getElementById('svc-3-price'), base:125},
          {el:document.getElementById('price-single'), base:150},
          {el:document.getElementById('price-package'), base:780}
        ];

        function animateValue(el, start, end, duration){
          let startTime = null;
          const formatter = v => '$' + Math.round(v);
          function step(timestamp){
            if(!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime)/duration, 1);
            const value = start + (end - start) * ease(progress);
            el.textContent = formatter(value);
            if(progress < 1) requestAnimationFrame(step);
          }
          requestAnimationFrame(step);
        }
        function ease(t){return (--t)*t*t+1}

        function setMode(mode){
          modeButtons.forEach(b=>b.classList.toggle('active', b.dataset.mode===mode));
          if(mode === 'single'){
            // per-session view: show base, package as total
            animateValue(document.getElementById('svc-2-price'), 0, 780, 520);
            animateValue(document.getElementById('svc-1-price'), 0, 150, 520);
            animateValue(document.getElementById('svc-3-price'), 0, 125, 520);
            animateValue(document.getElementById('price-single'), 0, 150, 520);
            animateValue(document.getElementById('price-package'), 0, 780, 520);
          } else {
            // package view: show effective per-session for package
            animateValue(document.getElementById('svc-2-price'), 0, 780, 520);
            animateValue(document.getElementById('svc-1-price'), 0, Math.round(780/6), 520);
            animateValue(document.getElementById('svc-3-price'), 0, 125, 520);
            animateValue(document.getElementById('price-single'), 0, Math.round(780/6), 520);
            animateValue(document.getElementById('price-package'), 0, 780, 520);
          }
        }

        toggle.addEventListener('click', function(e){
          const btn = e.target.closest('button');
          if(!btn) return;
          setMode(btn.dataset.mode);
        });

        // initialize
        setMode('single');
      })();
    </script>
  </body>
</html>"} 
