  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>Method & Approach — {{BUSINESS_NAME}}</title>
    <style>
      :root{--bg:#fffdfa;--card:#ffffff;--muted:#4a4f56;--accent:#3b6f75;--accent-2:#8b5fbf;--cta:#1f5b5b}
      body{font-family:Inter, system-ui, -apple-system, Roboto, Arial;line-height:1.5;margin:0;background:var(--bg);color:#071127}
      .wrap{max-width:980px;margin:0 auto;padding:20px}
      header{display:flex;align-items:center;justify-content:space-between;padding:16px 0}
      nav a{margin-left:12px;text-decoration:none;color:#071127;font-weight:700}
      .hero{padding:20px;border-radius:12px;background:linear-gradient(90deg,rgba(59,111,117,0.04),transparent);margin-bottom:18px}
      h1{margin:0;font-size:24px}
      .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
      .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 14px 40px rgba(12,24,56,0.06)}
      .muted{color:var(--muted)}
      .pill{display:inline-block;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;padding:6px 10px;border-radius:999px;font-weight:700}
      .method-visual{height:160px;border-radius:10px;background:linear-gradient(180deg,rgba(59,111,117,0.06),transparent);display:flex;align-items:center;justify-content:center}
