      .mood button{padding:8px 12px;border-radius:999px;border:1px solid rgba(12,24,56,0.06);background:#fff;cursor:pointer;font-weight:700}
      .mood button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}
      .method-detail{transition:all 300ms ease;border-radius:10px;padding:14px;margin-top:12px}
      .fade-out{opacity:0;transform:translateY(6px)}
      .cta{display:inline-block;background:var(--cta);color:#fff;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:800}
      .small{font-size:13px;color:var(--muted)}
    </style>
  </head>
  <body>
    <div class="wrap">
      <header>
        <div style="display:flex;align-items:center;gap:12px">
          <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:900">TP</div>
          <div>
            <div style="font-weight:900">{{BUSINESS_NAME}}</div>
            <div class="small">Thoughtful therapy shaped to your life</div>
          </div>
        </div>
        <nav>
          <a href="index.html">Home</a>
          <a href="about.html">Story</a>
          <a href="specialties.html">Services</a>
          <a href="approach.html" aria-current="page">Method</a>
          <a href="contact.html">Reach</a>
        </nav>
      </header>

      <section class="hero">
        <h1>Method: a practical compass for change</h1>
        <p class="muted">I blend skill-building with simple plans. We translate intents into daily moves so therapy fits your life—small experiments, honest checks, and steady review.</p>
      </section>

      <div class="grid">
        <div>
          <div class="card">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div class="pill">Evidence-informed</div>
                <h3 style="margin:8px 0 0 0">What to expect in the first month</h3>
                <p class="small">We clarify priorities, try manageable interventions, and create a short plan you can test between sessions. The goal is useful changes you can notice.</p>
              </div>
              <div class="method-visual" aria-hidden="true"> 
                <svg width="140" height="100" viewBox="0 0 140 100" xmlns="http://www.w3.org/2000/svg">
                  <defs>
                    <linearGradient id="g1" x1="0" x2="1">
                      <stop offset="0" stop-color="#6a5aa6"/>
                      <stop offset="1" stop-color="#3b6f75"/>
                    </linearGradient>
                  </defs>
                  <rect x="6" y="10" width="128" height="78" rx="10" fill="#fff" stroke="url(#g1)" stroke-width="2"/>
                  <circle cx="36" cy="44" r="10" fill="url(#g1)"/>
                  <rect x="60" y="34" width="60" height="6" rx="3" fill="#dfe8e8"/>
