      // Mood-to-Method (Approach page) - morphing content + CTA update
      (function(){
        const mapping = {
          overwhelmed: {title: 'Short stabilization plan', body: 'A two-step stabilization plan: 1) a single daily anchor practice, 2) one priority pared down for the day. We test feasibility and adjust.', cta: 'Request a stabilization consult'},
          stuck: {title: 'A focused experiment', body: 'We create a 7-day behavioral experiment—small, measurable, and time-limited—to test a change and gather useful feedback.', cta: 'Start a 7-day plan'},
          avoid: {title: 'Gentle activation', body: 'We use graded exposure and values-based activation: small steps that reduce avoidance while honoring your pace.', cta: 'Plan a gentle series'},
          anxious: {title: 'Pacing and regulation', body: 'Short regulation strategies paired with cognitive work to slow reactivity and build a sense of control in key moments.', cta: 'Book a calming session'}
        };

        const container = document.getElementById('mood-app');
        const card = document.getElementById('method-card');
        const title = document.getElementById('method-title');
        const body = document.getElementById('method-body');
        const cta = document.getElementById('mood-cta');

        container.addEventListener('click', function(e){
          const btn = e.target.closest('button');
          if(!btn) return;
          const key = btn.dataset.key;
          Array.from(container.querySelectorAll('button')).forEach(b=>b.classList.remove('active'));
          btn.classList.add('active');

          // simple morph animation
          card.classList.add('fade-out');
          setTimeout(()=>{
            title.textContent = mapping[key].title;
            body.textContent = mapping[key].body;
            cta.textContent = mapping[key].cta;
            // keep CTA url flexible: point to booking with a query param
            const url = new URL('{{PRIMARY_CTA_URL}}', window.location.href);
            url.searchParams.set('focus', key);
            cta.setAttribute('href', url.toString());
            card.classList.remove('fade-out');
          }, 220);
        });
      })();
    </script>
